"""Render expanded silver diagnostics without promoting them to independent gold."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
NAMES=['baseline','yake3','yake5','textrank2','textrank4','yake_morph','spacy','embeddings','rule_yake','rule_textrank','rule_spacy','rule_embeddings','rule_spacy_embeddings']
def load_rows(split):return [json.loads(s) for s in (ROOT/f'datasets/expanded/{split}.jsonl').read_text().splitlines()]
def fmt(x):return 'N/A' if x is None else f'{x:.3f}'
def main():
 s=json.loads((ROOT/'datasets/expanded/summary.json').read_text());reports={n:json.loads((ROOT/f'results/expanded-silver/{n}.json').read_text()) for n in NAMES}
 refs=load_rows('development')+load_rows('test')
 lines=['# Расширенная разметка агентом — 27 октября 2026','',
 '## Что сделано','',
 'Пользователь поручил разметку агенту. По всем 98 исходным фрагментам сохранено явное решение: аннотация, осознанное отсутствие подсветки или исключение по качеству извлечения. Выходы алгоритмов не применяются в коде построения разметки. У агента был доступ к прежнему пилоту; полной независимости и слепой валидации не заявляем.',
 '',f'Пригодная выборка: **{s["reviewed_examples"]} примера, {s["words"]} слов, {sum(s["label_counts"].values())} выделения и {s["negative_examples"]} явных NONE**. Development — 54 примера из 14 документов; test — 20 примеров из 6 документов. Источники не пересекаются, все шесть тематик представлены в test.',
 '', '| Категория | Количество |','|---|---:|']
 for label,count in s['label_counts'].items():lines.append(f'| {label} | {count} |')
 lines+=['', 'Точные границы заданы в Unicode code points [start,end), для каждого диапазона сохранён ожидаемый текст. Категории тела определения и его термина размечены отдельно; смысл и визуальный рендеринг не смешиваются. Предпочтение — ограниченному набору содержательных фрагментов, не всем существительным. Повторное упоминание выбранной фразы обычно не выделяется.',
 '', '## Качество источников','',
 '24 исходных фрагмента содержат разрушенное извлечение формул: раздробленные символы дублируются сырой записью displaystyle. Ещё один начинается внутри слова после такой формулы. Эти 25 фрагментов исключены с причинами и хэшами, а не превращены в отрицательные примеры. Один дословный законченный префикс статьи об интеграле восстановлен как отдельный дочерний фрагмент: формулу не исправляли, источник и test-раздел сохранили.',
 '', 'Четыре отрицательных примера — два библиографических списка и два периферийных рассказа об этимологии/публикации. Они находятся в development. В естественном test данного прохода NONE нет: специфичность на отрицательных test-примерах не измерена. Для окончательного сравнения потребуются новые отрицательные источники, а не перенос development-примеров в test.',
 '', 'Файлы: [политика](../annotation/README.md), [явные решения агента](../annotation/decisions.py), [сводка](../datasets/expanded/summary.json), [исключения](../datasets/expanded/excluded.json). Атрибуция и CC BY-SA 4.0 наследуются от [источников](../datasets/sources.json) и [лицензии датасета](../datasets/LICENSE.md). Исходные 98 текстов и прежние результаты сохранены без изменений.',
 '', '## Повторное сравнение: параметры не менялись','',
 'Выполнены новые предсказания тех же 13 конфигураций, offline CPU. Модели, top-k, пороги и правила не подбирались по новой разметке. Прежние замеры скорости и RAM не пересчитывались и не приписываются этому проходу.',
 '', 'Общая задача таблицы — TERM: DEFINITION_TERM + KEY_TERM. В test 49 таких эталонных диапазонов. Дополнительный термин, посчитанный FP, может быть полезен при иной политике: это несовпадение с одной агентской разметкой, а не доказанная бессмысленность.',
 '', '| Метод | Dev F1 exact | Test P | Test R | Test F1 exact | F1 overlap | TP | FP | FN | 95% source-bootstrap |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---|']
 for n in NAMES:
  d=reports[n];q=d['quality']['test'];m=q['term_exact'];ci=q['source_bootstrap_term_f1_95']
  lines.append(f'| {n} | {fmt(d["quality"]["development"]["term_exact"]["f1"])} | {fmt(m["precision"])} | {fmt(m["recall"])} | {fmt(m["f1"])} | {fmt(q["term_overlap"]["f1"])} | {m["tp"]} | {m["fp"]} | {m["fn"]} | {ci[0]:.3f}–{ci[1]:.3f} |')
 lines+=['', 'Интервалы получены 1000 повторными выборками шести исходных документов, а не независимых абзацев. Они не включают неопределённость агентской разметки. Overlap разрешает любое положительное пересечение и потому является мягкой диагностикой, не точным совпадением границ.',
 '', '## Категории, которые действительно поддерживает baseline','',
 'Тела определений DEFINITION не извлекает ни один текущий адаптер. Их 64 аннотации подготовлены для дальнейшей разработки; сравнивать keyword-методы по этой категории как полноценные классификаторы было бы неверно. IMPORTANT и EXAMPLE присутствуют только у baseline и rule_* гибридов. Ниже descriptive test-F1 по ним; самостоятельные YAKE/TextRank/embedding-адаптеры здесь не оцениваются.',
 '', '| Пайплайн | IMPORTANT F1 | EXAMPLE F1 |','|---|---:|---:|']
 for n in NAMES:
  if n=='baseline' or n.startswith('rule_'):
   per=reports[n]['quality']['test']['taxonomy_diagnostic']['per_category'];lines.append(f'| {n} | {fmt(per["IMPORTANT"]["f1"])} | {fmt(per["EXAMPLE"]["f1"])} |')
 lines+=['', 'Это разметка семантической важности и примеров без обязательных маркеров. Правила v0.1 намеренно ограничены явными вводными конструкциями и не должны позиционироваться как решающие всю эту задачу. Полные per-category precision/recall/F1 и macro F1 сохранены в JSON как диагностические значения; итоговый macro по всей таксономии не используется для выбора победителя.',
 '', '## Конкретные наблюдения','',
 '- Ни один вариант пока не даёт достаточного покрытия выбранных терминов при одновременно малом количестве лишних выделений. Повышение числа кандидатов само по себе не означает полезного улучшения.',
 '- Сложные гибриды существенно расходуют память в прежних ресурсных замерах; новая разметка не даёт основания оправдать их внедрение во время печати.',
 '- Трёхкомпонентный прототип получает от spaCy до пяти кандидатов и выбирает до пяти после embedding-ранжирования. Без большего пула или порога отбора он в основном переставляет уже выбранные фразы; различия могут возникать из-за порядка разрешения пересечений. Поэтому равные результаты rule_spacy и rule_spacy_embeddings не доказывают бесполезность эмбеддингов вообще: это ограничение конкретного адаптера.',
 '- Точные границы, словоформы, выбор первого упоминания, длинные именные группы и top-k ограничивают качество. Оценка на этих предпочтениях не является объективной оценкой всей учебной важности.',
 '', 'Пример из development: проявления электрического тока. Ниже сохранена фактическая выдача без подгонки reference:', '']
 case=next(r for r in refs if r['parent_id']=='wiki_29983_2')
 lines+=['Выбрано агентом: '+', '.join(a['text'] for a in case['annotations'] if a['label'] in ['KEY_TERM','DEFINITION_TERM'])+'.','']
 for n in ['baseline','yake5','spacy','rule_spacy_embeddings']:
  predictions=[json.loads(x) for x in (ROOT/f'results/expanded-silver/predictions-{n}.jsonl').read_text().splitlines()];p=next(x for x in predictions if x['id']==case['id']);terms=[a['text'] for a in p['annotations'] if a['label'] in ['KEY_TERM','DEFINITION_TERM']]
  lines.append('- **'+n+'**: '+('; '.join(terms) or '(нет терминов)'))
 lines+=['', '## Решение для следующего этапа','',
 '**Победитель по качеству не объявлен.** Для текущей стабильной версии сохраняем TypeScript-правила. Агентская разметка теперь достаточна для воспроизводимого поиска ошибок и exploratory разработки, но не для заявления об оптимальном NLP-движке.',
 '', 'Приоритеты разработки в отдельном эксперименте: осторожные определения через тире; отсеивание глагольных ложных субъектов; корректная генерация более широкого пула составных фраз; ограничение плотности подсветки. Настраивать эти решения можно только на development, а окончательную проверку проводить на новых источниках: существующий test уже наблюдался в предыдущем пилоте. Для Deep Mode отдельно проверить минимальное spaCy-окружение без optional torch и осмысленный отбор из расширенного пула кандидатов. Ничего из этого автоматически не добавляется в main.',
 '', '## Проверки и сохранение','',
 '- Пройдены 19 исследовательских тестов: прежние метрики/человеческий импорт и 6 новых тестов корпуса, происхождения, исключений и границ.',
 '- Каждое из 98 исходных решений зафиксировано; все 342 подстроки проверены, SHA-256 исходных текстов и source-disjoint разбиение сохранены.',
 '- Код references не читает outputs адаптеров. Хэши двух expanded reference-файлов записаны в каждом результате сравнения.',
 '- Основные gold-метрики по-прежнему отсутствуют. Нет новой независимой человеческой проверки, межэкспертного согласия или unseen final test.',
 '- Стабильный main и тег v0.1.1-stable не менялись. Изменения предназначены только для исследовательского draft PR №1.']
 (ROOT/'reports/expanded-silver.md').write_text('\n'.join(lines)+'\n');print('Expanded report written')
if __name__=='__main__':main()
